addEventListener('keydown',e=>{if($('help-dialog').open)return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='ShiftLeft')keys.add(e.code);if(e.code==='KeyE'&&!e.repeat&&mode==='lot')doInteraction();if(e.code==='Escape'){if(performing)cancelAction();else if(mode==='lot')leaveLot();}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();joy={x:0,y:0};$('joystick-knob').style.transform='';});document.addEventListener('visibilitychange',()=>{paused=document.hidden;clock.getDelta();keys.clear();});
